import sys
from pathlib import Path

# Add project root to path for src imports
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from benchmark_config import BenchmarkConfig
from benchmark_runner import BenchmarkRunner
from plot_maker import PlotMaker
from src.config import MandelbrotConfig


def main():
    config = BenchmarkConfig(
        mb_config=MandelbrotConfig(
            xmin=-2.0, xmax=1.0,
            ymin=-1.5, ymax=1.5,
            max_iter=100,
            chunk_size=128,
        ),
        calculators=["native", "numpy", "numba", "multiprocess"],
        resolutions=[64, 128, 256, 512, 1024],
        num_runs=3,
        warmup_runs=1,
    )

    print("Starting benchmark...")
    print(f"Calculators: {config.calculators}")
    print(f"Resolutions: {config.resolutions}")
    print(f"Runs per config: {config.num_runs} (+ {config.warmup_runs} warmup)\n")

    runner = BenchmarkRunner(config)
    results = runner.run()

    print("\nGenerating plots...")
    plotter = PlotMaker(results, output_dir=config.output_dir)
    plotter.make_all_plots(save=True, show=False)

    print("Done.")


if __name__ == "__main__":
    main()
